    /// <summary>
    /// Find method to fetch METExciseRegisterOriginTypes
    /// </summary>
    /// <param name = "_referenceId">ReferenceId reference</param>
    /// <param name = "_transactionType">Transaction type</param>
    /// <param name = "_forUpdate">Boolean to update</param>
    /// <returns>METExciseRegisterOriginTypes</returns>
    public static METExciseRegisterOriginTypes find(InventTransType         _referenceId,
                                                    METTransactionType      _transactionType,
                                                    boolean                 _forUpdate = false)
    {
        METExciseRegisterOriginTypes        metExciseRegisterOriginTypes;

        if (_forUpdate)
        {
            metExciseRegisterOriginTypes.selectForUpdate(true);
        }

        select firstonly metExciseRegisterOriginTypes
            where metExciseRegisterOriginTypes.ReferenceId == _referenceId  &&
                metExciseRegisterOriginTypes.TransactionType == _transactionType;

        return metExciseRegisterOriginTypes;
    }

/// <summary>
/// Exist method to fetch existance of record
/// </summary>
/// <param name = "_referenceId">ReferenceId reference</param>
/// <param name = "_transactionType">Transaction type</param>
/// <returns>Boolean</returns>
public static boolean exist(InventTransType         _referenceId,
                            METTransactionType      _transactionType)
{
    return (select firstonly RecId from metExciseRegisterOriginTypes
                where metExciseRegisterOriginTypes.ReferenceId == _referenceId  &&
                    metExciseRegisterOriginTypes.TransactionType == _transactionType).RecId != 0;
}

    /// <summary>
    /// Validates the integrity of specific fields within the METExciseRegisterOriginTypes table.
    /// This method extends the standard field validation to include custom business logic,
    /// ensuring that 'CreateDutyCredit' is only enabled if 'UpdateRegister' is also active.
    /// </summary>
    /// <param name = "_fieldIdToCheck">The ID of the field to be validated.</param>
    /// <returns>Returns true if the field passes validation, false otherwise.</returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        if (ret)
        {
            switch(_fieldIdToCheck)
            {
                case fieldNum(METExciseRegisterOriginTypes, CreateDutyCredit) :
                    if (this.CreateDutyCredit && !this.UpdateRegister)
                    {
                        ret = checkFailed("@MET:CreateDutyForUpdateRegister");
                    }
                break;

                case fieldNum(METExciseRegisterOriginTypes, UpdateLodgement) :
                case fieldNum(METExciseRegisterOriginTypes, UpdateCPLodgement) :
                    if (this.UpdateLodgement && this.UpdateCPLodgement)
                    {
                        ret = checkFailed("@MET:UpdateLodgementCPError");
                    }
                break;

                default:
                    break;
            }
            
        }
    
        return ret;
    }

    /// <summary>
    /// Handles actions when a field value is modified on the METExciseRegisterOriginTypes table.
    /// </summary>
    /// <param name="_fieldId">The ID of the field that was modified.</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(METExciseRegisterOriginTypes, UpdateRegister) :
                    if (!this.UpdateRegister)
                    {
                        this.CreateDutyCredit = false;
                    }
            break;
        }
            
    }
